-- Current database schema (public), generated by `npm run db:state` — do not edit by hand.
-- Migrated up to: 0088_otel_cost_attribution. Source of truth: server/drizzle/migrations/*.sql.
-- Comments come from COMMENT ON in the migrations; add one when a table or column is not
-- obvious from its name and type.

CREATE TYPE export_import_job_kind AS ENUM ('export', 'import', 'staged_upload');
CREATE TYPE export_import_job_status AS ENUM ('staged', 'running', 'done', 'error');
CREATE TYPE team_access_mode AS ENUM ('transparent', 'restricted');
CREATE TYPE upload_queue_status AS ENUM ('pending', 'processing', 'partially_uploaded', 'failed', 'rejected_foreign_session');
CREATE TYPE user_role AS ENUM ('admin', 'user');

-- Latest npm stable/latest versions per AI tool (claude-code); written by AiToolVersionsService, last_attempt_at is the cluster fetch claim.
CREATE TABLE ai_tool_version (
  tool_name character varying(64) NOT NULL,
  -- {stable, latest} npm dist-tags; NULL until the first successful fetch.
  version_map jsonb,
  fetched_at timestamp with time zone,
  last_attempt_at timestamp with time zone,
  CONSTRAINT ai_tool_version_pkey PRIMARY KEY (tool_name)
);

-- Append-only history of distinct {stable, latest} maps per tool; written by AiToolVersionsService.
CREATE TABLE ai_tool_version_history (
  id serial,
  tool_name character varying(64) NOT NULL,
  version_map jsonb NOT NULL,
  effective_from timestamp with time zone NOT NULL,
  CONSTRAINT ai_tool_version_history_pkey PRIMARY KEY (id)
);
CREATE INDEX ai_tool_version_history_tool_effective_idx ON ai_tool_version_history (tool_name, effective_from);

-- Per-user API keys used by the hook; written by ApiKeysService. Only the hash is stored.
CREATE TABLE api_keys (
  id serial,
  user_id integer NOT NULL,
  name character varying(1000) NOT NULL,
  -- Short plaintext prefix of the key, used to find the row before the hash is checked.
  slug character varying(6) NOT NULL,
  key_hash character varying NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  -- NULL = never expires.
  expires_at timestamp with time zone,
  CONSTRAINT api_keys_pkey PRIMARY KEY (id),
  CONSTRAINT api_keys_user_id_name_unique UNIQUE (user_id, name),
  CONSTRAINT api_keys_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX api_keys_slug_idx ON api_keys (slug);
CREATE INDEX idx_api_keys_user_id ON api_keys (user_id);

-- Distinct context key/value pairs found in artisyn event lines; written by LogsService ingest, orphans deleted on session purge.
CREATE TABLE contexts (
  id serial,
  context_key character varying(255) NOT NULL,
  context_value character varying(4000) NOT NULL,
  CONSTRAINT contexts_pkey PRIMARY KEY (id),
  CONSTRAINT contexts_context_key_context_value_unique UNIQUE (context_key, context_value)
);

-- Audit trail, one row per deleted session ever; written by SessionsService before purge. No FKs: the session may already be gone.
CREATE TABLE deleted_session_log (
  id serial,
  session_id character varying(255) NOT NULL,
  -- sessions.id of the deleted session; unique, also the claim that keeps concurrent retention purges idempotent.
  session_pk integer NOT NULL,
  owner_user_id integer,
  -- NULL = removed by the automatic retention purge, not by a user.
  deleted_by_user_id integer,
  deleted_at timestamp with time zone DEFAULT now() NOT NULL,
  start_time timestamp with time zone,
  end_time timestamp with time zone,
  work_time_ms bigint,
  -- Computed tree cost in USD at deletion time; NULL = unpriced.
  total_cost numeric(14,8),
  CONSTRAINT deleted_session_log_pkey PRIMARY KEY (id)
);
CREATE INDEX deleted_session_log_deleted_at_idx ON deleted_session_log (deleted_at);
CREATE INDEX deleted_session_log_deleted_by_idx ON deleted_session_log (deleted_by_user_id);
CREATE UNIQUE INDEX deleted_session_log_session_pk_unique ON deleted_session_log (session_pk);

-- One-time email-confirmation tokens (24 h TTL); written by EmailConfirmationTokensService. Rows are marked consumed, never deleted.
CREATE TABLE email_confirmation_tokens (
  id serial,
  user_id integer NOT NULL,
  token character varying NOT NULL,
  expires_at timestamp with time zone NOT NULL,
  -- Set when the token is consumed or invalidated by a newer token; NULL = still usable until expires_at.
  consumed_at timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT email_confirmation_tokens_pkey PRIMARY KEY (id),
  CONSTRAINT email_confirmation_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX idx_email_confirmation_tokens_token ON email_confirmation_tokens (token);
CREATE INDEX idx_email_confirmation_tokens_user_id ON email_confirmation_tokens (user_id);

-- Background session export, import and staged-upload jobs; written by ExportImportJobsService, old terminal rows removed by ExportImportJobCleanupScheduler.
CREATE TABLE export_import_jobs (
  -- App-generated UUID (staged_upload rows: UUID.zip, also the staged file name).
  id character varying(64) NOT NULL,
  kind export_import_job_kind NOT NULL,
  status export_import_job_status NOT NULL,
  processed integer DEFAULT 0 NOT NULL,
  total integer DEFAULT 0 NOT NULL,
  error_message text,
  result_file_path character varying,
  result_file_name character varying,
  -- NULL for a bootstrap-import staged upload until it is confirmed.
  repo_id integer,
  user_id integer,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT export_import_jobs_pkey PRIMARY KEY (id),
  CONSTRAINT export_import_jobs_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE,
  CONSTRAINT export_import_jobs_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_export_import_jobs_repo_id ON export_import_jobs (repo_id);
CREATE INDEX idx_export_import_jobs_status_updated_at ON export_import_jobs (status, updated_at);
CREATE INDEX idx_export_import_jobs_user_id ON export_import_jobs (user_id);

-- Inventory of harness elements (skills, rules, MCP servers, tools) a repository has reported; upserted by harness-elements-writer.ts on artisyn ingest, never derived from usage.
CREATE TABLE harness_elements (
  id serial,
  repo_id integer NOT NULL,
  -- skill | rule | mcp | tool.
  kind character varying(16) NOT NULL,
  name character varying(255) NOT NULL,
  mcp_server character varying(128),
  mcp_connected boolean,
  -- MCP-sourced tools only: estimated tool schema size in tokens (bytes / 4).
  schema_size_tokens integer,
  -- NULL for built-in tool rows, which are seeded and never removed.
  first_seen timestamp with time zone,
  -- Bumped on every re-report, never cleared; older than repositories.harness_inventory_reported_at = removed.
  last_seen timestamp with time zone,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  -- Skills only: project (.claude/skills) | plugin; NULL = older hook did not report it.
  source character varying(16),
  CONSTRAINT harness_elements_pkey PRIMARY KEY (id),
  CONSTRAINT harness_elements_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX harness_elements_repo_kind_name_unique ON harness_elements (repo_id, kind, name);
CREATE INDEX idx_harness_elements_repo_id ON harness_elements (repo_id);

-- Hook-built harness snapshot bodies (skills, agents, MCP servers, system context), one per (owner, snapshot_id); inserted by harness-snapshot.ts on ingest, deleted when no session references the id.
CREATE TABLE harness_snapshots (
  id serial,
  user_id integer NOT NULL,
  -- Hook-computed content hash (64 hex); validated, never recomputed. The same id may exist under several owners.
  snapshot_id character varying(64) NOT NULL,
  body jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT harness_snapshots_pkey PRIMARY KEY (id),
  CONSTRAINT harness_snapshots_user_id_snapshot_id_key UNIQUE (user_id, snapshot_id),
  CONSTRAINT harness_snapshots_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_harness_snapshots_snapshot_id ON harness_snapshots (snapshot_id);

-- Team invitations; written by TeamsService. At most one pending invitation per (team_id, invitee_id).
CREATE TABLE invitations (
  id serial,
  team_id integer NOT NULL,
  inviter_id integer NOT NULL,
  invitee_id integer NOT NULL,
  -- pending | accepted | declined | cancelled (only pending rows are unique per team and invitee).
  status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT invitations_pkey PRIMARY KEY (id),
  CONSTRAINT invitations_invitee_id_fkey FOREIGN KEY (invitee_id) REFERENCES users(id),
  CONSTRAINT invitations_inviter_id_fkey FOREIGN KEY (inviter_id) REFERENCES users(id),
  CONSTRAINT invitations_team_id_fkey FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE
);
CREATE INDEX idx_invitations_invitee_id ON invitations (invitee_id);
CREATE INDEX idx_invitations_inviter_id ON invitations (inviter_id);
CREATE INDEX idx_invitations_team_id ON invitations (team_id);
CREATE UNIQUE INDEX invitations_pending_unique ON invitations (team_id, invitee_id) WHERE ((status)::text = 'pending'::text);

-- Links a log to its context pairs; written by LogsService ingest for newly inserted artisyn logs.
CREATE TABLE log_contexts (
  log_id integer NOT NULL,
  context_id integer NOT NULL,
  CONSTRAINT log_contexts_pkey PRIMARY KEY (log_id, context_id),
  CONSTRAINT log_contexts_context_id_fkey FOREIGN KEY (context_id) REFERENCES contexts(id),
  CONSTRAINT log_contexts_log_id_fkey FOREIGN KEY (log_id) REFERENCES logs(id) ON DELETE CASCADE
);

-- Single-row cache (id = 1) of the latest published Log Hub GitHub release, used for the admin new-release badge; written by LogHubReleaseService once per 24 h per cluster.
CREATE TABLE log_hub_release_check (
  -- Always 1 (CHECK constraint): the table holds at most one row.
  id smallint DEFAULT 1 NOT NULL,
  -- Last validated release tag, e.g. v1.3.0; NULL until the first successful fetch.
  latest_tag character varying(64),
  -- Validated html_url of that release on GitHub; NULL until the first successful fetch.
  release_url text,
  -- Time of the last successful fetch; NULL = never succeeded.
  fetched_at timestamp with time zone,
  -- Cluster claim: time of the last fetch attempt (success or failure); one attempt per 24 h across all instances.
  last_attempt_at timestamp with time zone,
  CONSTRAINT log_hub_release_check_pkey PRIMARY KEY (id),
  CONSTRAINT log_hub_release_check_id_check CHECK ((id = 1))
);

-- Links a log (in practice the artisyn log of a root session) to the repositories rows it belongs to; written by LogsService ingest and the repo URL backfill.
CREATE TABLE log_repositories (
  log_id integer NOT NULL,
  repo_id integer NOT NULL,
  CONSTRAINT log_repositories_pkey PRIMARY KEY (log_id, repo_id),
  CONSTRAINT log_repositories_log_id_fkey FOREIGN KEY (log_id) REFERENCES logs(id) ON DELETE CASCADE,
  CONSTRAINT log_repositories_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE
);
CREATE INDEX idx_log_repositories_repo_id_log_id ON log_repositories (repo_id, log_id);

-- One uploaded log per (session_id, log_type), the raw event lines in body; upserted by LogsService ingest and import.
CREATE TABLE logs (
  id serial,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  -- artisyn (hook events) | claude (transcript) | claude-subagent (sub-agent transcript) | claude-otel (normalised OTEL result) | tool-calls (CLI tool wrapper records).
  log_type character varying(50) NOT NULL,
  -- JSON array of the uploaded lines; for claude-otel a normalised summary, not raw OTLP.
  body jsonb NOT NULL,
  session_id integer NOT NULL,
  user_id integer NOT NULL,
  -- Extracted at write time from artisyn logs only; NULL for other log types (same for start_time, end_time, git_branch, git_repo_root, git_worktree_root).
  first_prompt text,
  -- Earliest activity timestamp of an artisyn log (synthetic non-activity lines skipped).
  start_time timestamp with time zone,
  -- Latest activity timestamp of an artisyn log (synthetic non-activity lines skipped).
  end_time timestamp with time zone,
  git_branch text,
  -- Primary checkout root (git --git-common-dir) of the machine the session ran on; artisyn only.
  git_repo_root text,
  -- git rev-parse --show-toplevel of the session, differs from git_repo_root inside a linked worktree; artisyn only.
  git_worktree_root text,
  CONSTRAINT logs_pkey PRIMARY KEY (id),
  CONSTRAINT logs_session_id_log_type_unique UNIQUE (session_id, log_type),
  CONSTRAINT logs_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id),
  CONSTRAINT logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_logs_artisyn_with_prompt ON logs (session_id, start_time, user_id) WHERE (((log_type)::text = 'artisyn'::text) AND (first_prompt IS NOT NULL));
CREATE INDEX idx_logs_log_type ON logs (log_type);
CREATE INDEX idx_logs_user_id ON logs (user_id);
CREATE INDEX idx_logs_user_id_log_type_start_time ON logs (user_id, log_type, start_time) WHERE (first_prompt IS NOT NULL);

-- Raw OTEL chunks, one row per receiver file (one inbound OTLP request); upserted by LogsService ingestOtelChunk.
CREATE TABLE logs_otel (
  id serial,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  session_id integer NOT NULL,
  user_id integer NOT NULL,
  -- Receiver file name; unique per session so a re-uploaded chunk replaces its row.
  chunk_key character varying(255) NOT NULL,
  received_at timestamp with time zone,
  body jsonb NOT NULL,
  -- Chunk cost in micro-USD; NULL = chunk has no api_request records.
  cost_usd_micros bigint,
  record_count integer,
  processed_at timestamp with time zone,
  -- NULL = pending OTEL facts projection; -1 = failed (retried at startup); N = projected by version N.
  otel_projection_version smallint,
  CONSTRAINT logs_otel_pkey PRIMARY KEY (id),
  CONSTRAINT logs_otel_session_chunk_unique UNIQUE (session_id, chunk_key),
  CONSTRAINT logs_otel_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT logs_otel_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_logs_otel_projection_pending ON logs_otel (id) WHERE (otel_projection_version IS NULL);
CREATE INDEX idx_logs_otel_session_id ON logs_otel (session_id);
CREATE INDEX idx_logs_otel_session_received_at ON logs_otel (session_id, received_at);
CREATE INDEX idx_logs_otel_user_id ON logs_otel (user_id);

-- Model prices, one row per price version (model_id, effective_from); written by model-pricing-store.ts (daily Anthropic fetch, OpenRouter import, admin). Readers take the newest row with effective_from <= today.
CREATE TABLE model_pricing (
  -- Model id without the -YYYYMMDD suffix.
  model_id character varying NOT NULL,
  -- USD per million input tokens (price_out, price_cache_r, price_cache_w_5m, price_cache_w_1h likewise).
  price_in numeric(10,6) NOT NULL,
  price_out numeric(10,6) NOT NULL,
  price_cache_r numeric(10,6) NOT NULL,
  -- Legacy flat cache-write price (equals the 5m rate); no readers, kept to stay non-destructive.
  price_cache_w numeric(10,6) NOT NULL,
  currency character(3) DEFAULT 'USD'::bpchar NOT NULL,
  effective_from date NOT NULL,
  -- Estimation-only characters per token; NULL = not researched.
  chars_per_token numeric(6,3),
  context_length integer,
  price_cache_w_5m numeric(10,6) DEFAULT 0 NOT NULL,
  price_cache_w_1h numeric(10,6) DEFAULT 0 NOT NULL,
  -- USD per web-search request, not per million tokens; 0 for models without server tools.
  price_web_search numeric(10,6) DEFAULT 0 NOT NULL,
  -- anthropic | openrouter | manual | override; the effective row source is the model current source.
  source character varying(16) DEFAULT 'manual'::character varying NOT NULL,
  -- Prompt-length price tiers ascending by aboveTokens; NULL = no tiers.
  tiers jsonb,
  CONSTRAINT model_pricing_pkey PRIMARY KEY (model_id, effective_from),
  CONSTRAINT model_pricing_currency_check CHECK ((currency = 'USD'::bpchar)),
  CONSTRAINT model_pricing_source_check CHECK (((source)::text = ANY ((ARRAY['anthropic'::character varying, 'openrouter'::character varying, 'manual'::character varying, 'override'::character varying])::text[]))),
  CONSTRAINT model_pricing_tiers_array_chk CHECK (((tiers IS NULL) OR (jsonb_typeof(tiers) = 'array'::text)))
);

-- Status of each price source (anthropic, openrouter); the anthropic row is also the cluster claim for the daily fetch.
CREATE TABLE model_pricing_fetch_state (
  source character varying(16) NOT NULL,
  last_attempt_at timestamp with time zone,
  last_success_at timestamp with time zone,
  -- changed | unchanged | failed (anthropic); imported | failed (openrouter).
  last_result character varying(16),
  last_counts jsonb,
  last_error text,
  CONSTRAINT model_pricing_fetch_state_pkey PRIMARY KEY (source)
);

-- Per-model facts outside price versions: first sighting of an unpriced model and the base price hidden under an override; written by unpriced-model-registry.ts and model-pricing-store.ts.
CREATE TABLE model_pricing_meta (
  model_id character varying(255) NOT NULL,
  -- When ingest first saw the model without a price; never cleared.
  first_seen_at timestamp with time zone,
  -- Source of the base price kept under an active override (override_base_* columns); NULL = no override.
  override_base_source character varying(16),
  override_base_price_in numeric(10,6),
  override_base_price_out numeric(10,6),
  override_base_price_cache_r numeric(10,6),
  override_base_price_cache_w_5m numeric(10,6),
  override_base_price_cache_w_1h numeric(10,6),
  override_base_price_web_search numeric(10,6),
  override_base_chars_per_token numeric(6,3),
  override_base_context_length integer,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  override_base_tiers jsonb,
  CONSTRAINT model_pricing_meta_pkey PRIMARY KEY (model_id),
  CONSTRAINT model_pricing_meta_override_base_source_check CHECK (((override_base_source)::text = ANY ((ARRAY['anthropic'::character varying, 'openrouter'::character varying])::text[]))),
  CONSTRAINT model_pricing_meta_override_base_tiers_array_chk CHECK (((override_base_tiers IS NULL) OR (jsonb_typeof(override_base_tiers) = 'array'::text)))
);

-- Hook-built OKF knowledge-base snapshot bodies, one per (owner, snapshot_id); inserted by okf-snapshot.ts on ingest, deleted when no session references the id.
CREATE TABLE okf_snapshots (
  id serial,
  user_id integer NOT NULL,
  -- Hook-computed content hash (64 hex); validated, never recomputed.
  snapshot_id character varying(64) NOT NULL,
  body jsonb NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT okf_snapshots_pkey PRIMARY KEY (id),
  CONSTRAINT okf_snapshots_user_id_snapshot_id_key UNIQUE (user_id, snapshot_id),
  CONSTRAINT okf_snapshots_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- One row per OTEL api_request record, used to price utility calls the transcript does not show; written by ingestOtelChunk.
CREATE TABLE otel_api_calls (
  id serial,
  session_id integer NOT NULL,
  -- request_id, or <chunk_key>:<line index> when the record has none.
  call_key character varying(255) NOT NULL,
  request_id character varying(255),
  query_source character varying(255),
  model character varying(255),
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  -- All OTEL cache-creation tokens (telemetry has no TTL split).
  cache_write_5m_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_1h_tokens bigint DEFAULT 0 NOT NULL,
  web_search_requests bigint DEFAULT 0 NOT NULL,
  input_tokens_fast bigint DEFAULT 0 NOT NULL,
  output_tokens_fast bigint DEFAULT 0 NOT NULL,
  -- Claude Code reported cost in micro-USD.
  cost_usd_micros bigint,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT otel_api_calls_pkey PRIMARY KEY (id),
  CONSTRAINT otel_api_calls_session_call_unique UNIQUE (session_id, call_key),
  CONSTRAINT otel_api_calls_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_otel_api_calls_session_request_id ON otel_api_calls (session_id, request_id);

-- OTEL tab facts: one row per api_request call of a root session; written by otel-facts-writer.ts from the realtime channel and the chunk projection.
CREATE TABLE otel_calls (
  -- Always the root session; sub-agent calls are told apart by agent_id.
  session_id integer NOT NULL,
  -- request_id, else rec: + sha1 of the record.
  call_key character varying(300) NOT NULL,
  request_id character varying(255),
  query_source character varying(255),
  model character varying(255),
  claude_code_version character varying(64),
  prompt_id character varying(255),
  agent_id character varying(255),
  event_time timestamp with time zone NOT NULL,
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_tokens bigint DEFAULT 0 NOT NULL,
  cost_usd_micros bigint,
  -- main | subagent | hidden.
  structure character varying(16) NOT NULL,
  -- Classified before the transcript arrived; may be reclassified.
  provisional boolean NOT NULL,
  -- Bit 1 = seen on the realtime channel, bit 2 = seen in an uploaded chunk (confirmed).
  source_mask smallint NOT NULL,
  first_seq bigint NOT NULL,
  -- otel_session_state.seq of the write that last changed the row (delta cursor); first_seq = seq at insert.
  seq bigint NOT NULL,
  -- new | update | confirm | fill | reclass.
  change_kind character varying(8) NOT NULL,
  -- Cache-write tokens at the 5-minute TTL (OTEL cache_creation_5m_tokens); NULL = split not reported.
  cache_write_5m_tokens bigint,
  -- Cache-write tokens at the 1-hour TTL (OTEL cache_creation_1h_tokens); NULL = split not reported.
  cache_write_1h_tokens bigint,
  -- Reasoning effort of the call (OTEL effort); NULL = not reported.
  effort character varying(64),
  -- Speed mode of the call, e.g. fast (OTEL speed); NULL = not reported.
  speed character varying(64),
  -- Skill active for the call (OTEL skill.name); NULL = not reported.
  skill_name character varying(255),
  -- Plugin of the active skill or agent (OTEL plugin.name); NULL = not reported.
  plugin_name character varying(255),
  -- Sub-agent type name (OTEL agent.name), unlike agent_id which is the instance id; NULL = not reported.
  agent_name character varying(255),
  -- MCP server of the tool call that led to this request (OTEL mcp_server.name); NULL = not reported.
  mcp_server_name character varying(255),
  -- MCP tool of that tool call (OTEL mcp_tool.name); NULL = not reported.
  mcp_tool_name character varying(255),
  CONSTRAINT otel_calls_pk PRIMARY KEY (session_id, call_key),
  CONSTRAINT otel_calls_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT otel_calls_structure_check CHECK (((structure)::text = ANY ((ARRAY['main'::character varying, 'subagent'::character varying, 'hidden'::character varying])::text[])))
);
CREATE INDEX idx_otel_calls_session_agent ON otel_calls (session_id, agent_id) WHERE (agent_id IS NOT NULL);
CREATE INDEX idx_otel_calls_session_request_id ON otel_calls (session_id, request_id) WHERE (request_id IS NOT NULL);
CREATE INDEX idx_otel_calls_session_seq ON otel_calls (session_id, seq);

-- OTEL tab facts: 5-minute UTC cost rollups of otel_calls per root session and dimensions; written by otel-facts-writer.ts. Rows are zeroed, never deleted.
CREATE TABLE otel_cost_buckets (
  session_id integer NOT NULL,
  user_id integer,
  bucket_start timestamp with time zone NOT NULL,
  structure character varying(16) NOT NULL,
  -- Empty string = unknown (as for model and cc_version).
  query_source character varying(255) DEFAULT ''::character varying NOT NULL,
  model character varying(255) DEFAULT ''::character varying NOT NULL,
  cc_version character varying(64) DEFAULT ''::character varying NOT NULL,
  calls integer DEFAULT 0 NOT NULL,
  cost_usd_micros bigint DEFAULT 0 NOT NULL,
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_tokens bigint DEFAULT 0 NOT NULL,
  seq bigint NOT NULL,
  change_kind character varying(8) NOT NULL,
  -- Grain dimension from otel_calls.skill_name; empty string = not reported.
  skill character varying(255) DEFAULT ''::character varying NOT NULL,
  -- Grain dimension from otel_calls.mcp_server_name; empty string = not reported.
  mcp_server character varying(255) DEFAULT ''::character varying NOT NULL,
  -- Grain dimension from otel_calls.effort; empty string = not reported.
  effort character varying(64) DEFAULT ''::character varying NOT NULL,
  -- Grain dimension from otel_calls.speed; empty string = not reported.
  speed character varying(64) DEFAULT ''::character varying NOT NULL,
  CONSTRAINT otel_cost_buckets_pk PRIMARY KEY (session_id, bucket_start, structure, query_source, model, cc_version, skill, mcp_server, effort, speed),
  CONSTRAINT otel_cost_buckets_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT otel_cost_buckets_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX idx_otel_cost_buckets_session_seq ON otel_cost_buckets (session_id, seq);
CREATE INDEX idx_otel_cost_buckets_user_id ON otel_cost_buckets (user_id);

-- Sessions whose transcript request ids changed and whose root OTEL calls need reclassification; drained by OtelProjectionService.
CREATE TABLE otel_reclass_queue (
  session_id integer NOT NULL,
  queued_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT otel_reclass_queue_pkey PRIMARY KEY (session_id),
  CONSTRAINT otel_reclass_queue_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);

-- Per root session OTEL cursor and lock row every OTEL writer locks first; no row = session has no OTEL data.
CREATE TABLE otel_session_state (
  session_id integer NOT NULL,
  user_id integer,
  -- Per-root write counter, the since= cursor of the OTEL routes.
  seq bigint DEFAULT 0 NOT NULL,
  transcript_seq bigint,
  otel_hook_version character varying(32),
  has_spans boolean DEFAULT false NOT NULL,
  has_provisional boolean DEFAULT false NOT NULL,
  rt_last_at timestamp with time zone,
  chunk_last_at timestamp with time zone,
  -- Set when realtime batches were lost; cleared once chunks caught up.
  rt_gap_at timestamp with time zone,
  rt_receiver_id character varying(64),
  rt_batch_seq bigint,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  -- Claude account plan reported by OTEL (anthropic.plan), latest event wins; NULL = never reported.
  plan character varying(64),
  -- Account seat type reported by OTEL (anthropic.seat_type); NULL = never reported.
  seat_type character varying(64),
  -- API provider reported by OTEL (anthropic.provider); NULL = never reported.
  provider character varying(64),
  -- Custom API base URL reported by OTEL (anthropic.custom_base_url), stored without userinfo, query and fragment; NULL = never reported.
  custom_base_url character varying(1024),
  -- Event time of the newest OTEL record that set plan, seat_type, provider or custom_base_url; a field is overwritten only by a record at least this new.
  account_event_at timestamp with time zone,
  CONSTRAINT otel_session_state_pkey PRIMARY KEY (session_id),
  CONSTRAINT otel_session_state_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT otel_session_state_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX idx_otel_session_state_created_at ON otel_session_state (created_at);
CREATE INDEX idx_otel_session_state_user_id ON otel_session_state (user_id);

-- OTEL tab facts: one row per trace span of a root session; written by otel-facts-writer.ts.
CREATE TABLE otel_spans (
  session_id integer NOT NULL,
  trace_id character varying(64) NOT NULL,
  span_id character varying(32) NOT NULL,
  parent_span_id character varying(32),
  name character varying(255) NOT NULL,
  start_time timestamp with time zone NOT NULL,
  end_time timestamp with time zone,
  request_id character varying(255),
  agent_id character varying(255),
  query_source character varying(255),
  context character varying(32),
  -- Raw flattened span attributes, or {_truncated, _bytes} when too large.
  attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
  cost_usd_micros bigint,
  -- Own cost plus the rollups of all child spans, micro-USD.
  rollup_cost_usd_micros bigint,
  source_mask smallint NOT NULL,
  first_seq bigint NOT NULL,
  seq bigint NOT NULL,
  change_kind character varying(8) NOT NULL,
  CONSTRAINT otel_spans_pk PRIMARY KEY (session_id, trace_id, span_id),
  CONSTRAINT otel_spans_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_otel_spans_session_request_id ON otel_spans (session_id, request_id) WHERE (request_id IS NOT NULL);
CREATE INDEX idx_otel_spans_session_seq ON otel_spans (session_id, seq);

-- One-time password-reset tokens (1 h TTL); written by PasswordResetTokensService. Rows are marked used, never deleted.
CREATE TABLE password_reset_tokens (
  id serial,
  user_id integer NOT NULL,
  token character varying NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  expires_at timestamp with time zone NOT NULL,
  -- Set when the token is consumed or invalidated by a newer token; NULL = still usable until expires_at.
  used_at timestamp with time zone,
  CONSTRAINT password_reset_tokens_pkey PRIMARY KEY (id),
  CONSTRAINT password_reset_tokens_token_key UNIQUE (token),
  CONSTRAINT password_reset_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_password_reset_tokens_user_id ON password_reset_tokens (user_id);

-- History of repository code-size snapshots from the hook code-inventory event (denominator of "share of codebase touched"); written by repo-code-inventory.ts, pruned to the newest rows per repository.
CREATE TABLE repo_code_inventory (
  id serial,
  repo_id integer NOT NULL,
  captured_at timestamp with time zone NOT NULL,
  -- Empty string when unknown (never NULL, so the unique key stays idempotent).
  branch character varying(255) DEFAULT ''::character varying NOT NULL,
  commit_sha character varying(40),
  tracked_files integer NOT NULL,
  tracked_lines bigint NOT NULL,
  tracked_binary_files integer DEFAULT 0 NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT repo_code_inventory_pkey PRIMARY KEY (id),
  CONSTRAINT repo_code_inventory_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE
);
CREATE INDEX idx_repo_code_inventory_repo_captured_at ON repo_code_inventory (repo_id, captured_at);
CREATE UNIQUE INDEX repo_code_inventory_repo_captured_branch_unique ON repo_code_inventory (repo_id, captured_at, branch);

-- Personal analysis config (file categories, cache threshold, turn-end advisor) of one user for one repository row; written by RepositoriesService settings save.
CREATE TABLE repo_config (
  repo_id integer NOT NULL,
  user_id integer NOT NULL,
  -- RepoConfigJson; absent fields fall back to the team config, then to built-in defaults.
  config jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT repo_config_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE,
  CONSTRAINT repo_config_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_repo_config_repo_id ON repo_config (repo_id);
CREATE UNIQUE INDEX repo_config_repo_id_user_id_idx ON repo_config (repo_id, user_id) WHERE (user_id IS NOT NULL);

-- Personal list of monitored CLI tools for one repository row; written by ToolMonitorConfigService. No row = empty list.
CREATE TABLE repo_tool_monitor_config (
  repo_id integer NOT NULL,
  config jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT repo_tool_monitor_config_pkey PRIMARY KEY (repo_id),
  CONSTRAINT repo_tool_monitor_config_repo_id_fkey FOREIGN KEY (repo_id) REFERENCES repositories(id) ON DELETE CASCADE
);

-- One row per (user, canonical repo URL) the user uploaded sessions from; created by LogsService ingest, also holds the latest hook self-report.
CREATE TABLE repositories (
  id serial,
  -- Canonical URL from normalizeRepoUrl(); a repository without a git remote stores "<owner email>/<path>".
  repo_url character varying(4000) NOT NULL,
  user_id integer NOT NULL,
  -- Largest single artisyn upload body seen, in bytes; NULL until the first artisyn upload.
  max_upload_bytes bigint,
  -- Hook version from the latest hook-status event; NULL = no hook has reported for this repository.
  hook_version character varying(50),
  hook_last_activity timestamp with time zone,
  -- Last hook.log lines as of the latest report (string array), replaced on every report.
  hook_log_tail jsonb,
  hook_non_uploadable_logs jsonb,
  hook_recommendations jsonb,
  -- Time of the latest artisyn upload carrying a harness inventory self-report; NULL = never reported. Elements with an older last_seen are shown as removed.
  harness_inventory_reported_at timestamp with time zone,
  -- Whether the latest capable hook could probe MCP tools/list per tool; NULL = never reported by a capable hook.
  harness_mcp_per_tool_supported boolean,
  -- Latest CLI tool-wrapper status reported by the hook (written by the tool-usage rebuild, newest reportedAt wins); NULL = never reported.
  tool_wrap_status jsonb,
  CONSTRAINT repositories_pkey PRIMARY KEY (id),
  CONSTRAINT repositories_user_id_repo_url_unique UNIQUE (user_id, repo_url),
  CONSTRAINT repositories_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_repositories_repo_url ON repositories (repo_url);

-- Server-generated secrets shared by all cluster workers (today only session_secret, used when SESSION_SECRET is empty); written once by resolveSessionSecret() at startup.
CREATE TABLE server_secrets (
  name character varying(64) NOT NULL,
  value text NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT server_secrets_pkey PRIMARY KEY (name)
);

-- Current AI session attribution values of a session; written only by SessionAttributionService, a higher prompt_watermark replaces the whole row.
CREATE TABLE session_attribution (
  session_id integer NOT NULL,
  -- User-prompt count the values were evaluated at.
  prompt_watermark integer NOT NULL,
  -- Attribute values keyed by attribute key, typed by the team attribute definitions.
  values jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT session_attribution_pkey PRIMARY KEY (session_id),
  CONSTRAINT session_attribution_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_attribution_values_gin ON session_attribution USING gin ("values" jsonb_path_ops);

-- Append-only log of session attribution evaluations with their own cost; written by SessionAttributionService.
CREATE TABLE session_attribution_runs (
  id serial,
  session_id integer NOT NULL,
  prompt_watermark integer NOT NULL,
  eval_session_id character varying(255),
  -- session_id string of the invoking session, used by the executive summary join; NULL rows are excluded there.
  invoking_session_id character varying(255),
  started_at timestamp with time zone NOT NULL,
  finished_at timestamp with time zone NOT NULL,
  -- applied | ignored_stale | failed.
  outcome character varying(20) NOT NULL,
  model character varying(64),
  cost_usd numeric(12,6),
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_tokens bigint DEFAULT 0 NOT NULL,
  failure_reason text,
  CONSTRAINT session_attribution_runs_pkey PRIMARY KEY (id),
  CONSTRAINT session_attribution_runs_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_attribution_runs_session_id ON session_attribution_runs (session_id);

-- Per-call token arrays of a session transcript, input of the per-call tiered cost; rewritten with every session_stats upsert.
CREATE TABLE session_call_tokens (
  session_id integer NOT NULL,
  -- Columnar object: each key holds one number per call in first-seen order; a missing key reads as zeros.
  calls jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT session_call_tokens_pkey PRIMARY KEY (session_id),
  CONSTRAINT session_call_tokens_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT session_call_tokens_calls_object_chk CHECK ((jsonb_typeof(calls) = 'object'::text))
);

-- Per-session cache-creation tokens split by cause (compaction, file re-read, unattributed), per team or user scope; written by session-cause-stats-writer.ts and RepositoriesService recompute.
CREATE TABLE session_cause_stats (
  session_id integer NOT NULL,
  -- Set on team-scoped rows (NULL on user-scoped rows).
  team_id integer,
  user_id integer,
  -- High-cache-creation threshold the totals were computed with (a different current threshold = stale row).
  threshold integer NOT NULL,
  compaction_tokens bigint DEFAULT 0 NOT NULL,
  file_reread_tokens bigint DEFAULT 0 NOT NULL,
  unattributed_tokens bigint DEFAULT 0 NOT NULL,
  compaction_turns integer DEFAULT 0 NOT NULL,
  file_reread_turns integer DEFAULT 0 NOT NULL,
  unattributed_turns integer DEFAULT 0 NOT NULL,
  CONSTRAINT session_cause_stats_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT session_cause_stats_team_id_fkey FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
  CONSTRAINT session_cause_stats_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_cause_stats_session_id ON session_cause_stats (session_id);
CREATE UNIQUE INDEX idx_session_cause_stats_session_team ON session_cause_stats (session_id, team_id) WHERE (team_id IS NOT NULL);
CREATE UNIQUE INDEX idx_session_cause_stats_session_user ON session_cause_stats (session_id, user_id) WHERE (user_id IS NOT NULL);

-- Per-session changed-path facts, one row per logical file; written by session-changed-paths-writer.ts on transcript ingest, renormalised when the repo root arrives.
CREATE TABLE session_changed_paths (
  session_id integer NOT NULL,
  -- Row identity: case-folded repo-relative path, else the case-folded raw path (truncated to 1024 chars).
  path_key character varying(1024) NOT NULL,
  -- First raw spelling seen, kept so the path can be renormalised without re-reading the transcript.
  raw_path character varying(1024) NOT NULL,
  -- Repo-relative path in original case; NULL when outside the repo or the repo root is unknown (as are all normalised columns).
  rel_path text,
  rel_path_key text,
  folder text,
  folder_key text,
  top_module_key text,
  depth integer,
  -- Fixed taxonomy: source | test | config | docs | other (not the repo_config categories).
  file_kind character varying(16),
  extension character varying(32),
  -- true = resolved outside the repository; false with NULL rel_path = repo root never learned.
  outside_repo boolean DEFAULT false NOT NULL,
  -- added | modified (deleted is reserved, never written).
  change_kind character varying(16) NOT NULL,
  edit_calls integer DEFAULT 0 NOT NULL,
  diff_covered_calls integer DEFAULT 0 NOT NULL,
  lines_added integer DEFAULT 0 NOT NULL,
  lines_removed integer DEFAULT 0 NOT NULL,
  CONSTRAINT session_changed_paths_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_changed_paths_session_folder ON session_changed_paths (session_id, folder_key);
CREATE INDEX idx_session_changed_paths_session_id ON session_changed_paths (session_id);
CREATE UNIQUE INDEX session_changed_paths_session_path_key_unique ON session_changed_paths (session_id, path_key);

-- Stored computed cost of each session and its breakdown, read by every cost surface; written by recomputeSessionCosts (ingest and the stale-row sweeper).
CREATE TABLE session_costs (
  session_id integer NOT NULL,
  -- session_stats.model with any -YYYYMMDD suffix removed.
  model_id character varying,
  -- Price date of the top ancestor session; selects the model_pricing row in effect.
  price_date date NOT NULL,
  pricing_effective_from date,
  pricing_source character varying(16),
  -- Total cost in USD; NULL = unpriced (breakdown columns are then NULL too).
  cost double precision,
  cost_input double precision,
  cost_output double precision,
  cost_cache_read double precision,
  cost_cache_write_5m double precision,
  cost_cache_write_1h double precision,
  cost_web_search double precision,
  cost_fast_surcharge double precision,
  -- Informational: cost minus the same tokens at base rates; never part of the total.
  cost_tier_delta double precision,
  -- unknown-model or NULL.
  unavailable_reason character varying(32),
  -- true = needs recompute (price changed or ancestor price date changed); cleared by the sweeper.
  stale boolean DEFAULT false NOT NULL,
  computed_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT session_costs_pkey PRIMARY KEY (session_id),
  CONSTRAINT session_costs_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_costs_model_date ON session_costs (model_id, price_date);
CREATE INDEX idx_session_costs_stale ON session_costs (session_id) WHERE stale;

-- Per-session file reads per repo_config category, one row set per team scope and per user scope; written by session-file-stats-writer.ts.
CREATE TABLE session_file_stats (
  session_id integer NOT NULL,
  category_name character varying(64) NOT NULL,
  file_count integer DEFAULT 0 NOT NULL,
  -- Characters (UTF-16 units) of Read results returned into the context, not file size on disk.
  byte_count bigint DEFAULT 0 NOT NULL,
  -- Set on team-scoped rows (NULL on user-scoped rows).
  team_id integer,
  -- Set on user-scoped rows (NULL on team-scoped rows).
  user_id integer,
  CONSTRAINT session_file_stats_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT session_file_stats_team_id_fkey FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
  CONSTRAINT session_file_stats_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT session_file_stats_scope_check CHECK ((((team_id IS NOT NULL) AND (user_id IS NULL)) OR ((team_id IS NULL) AND (user_id IS NOT NULL))))
);
CREATE INDEX idx_session_file_stats_session_id ON session_file_stats (session_id);
CREATE UNIQUE INDEX session_file_stats_session_id_category_name_team_id_idx ON session_file_stats (session_id, category_name, team_id) WHERE (team_id IS NOT NULL);
CREATE UNIQUE INDEX session_file_stats_session_id_category_name_user_id_idx ON session_file_stats (session_id, category_name, user_id) WHERE (user_id IS NOT NULL);

-- Per-session harness element usage (tools, MCP, skills, rules); tool/MCP rows rebuilt from the transcript, skill/rule rows upserted from the artisyn inventory, by session-harness-usage-writer.ts.
CREATE TABLE session_harness_usage (
  session_id integer NOT NULL,
  kind character varying(16) NOT NULL,
  name character varying(255) NOT NULL,
  mcp_server character varying(128),
  -- Call count for tool/mcp rows; always 1 for skill/rule rows (loaded into context).
  uses integer DEFAULT 0 NOT NULL,
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  -- Tool rows only: available from session start (not added later by a deferred-tools delta); NULL for other kinds.
  is_initial boolean,
  CONSTRAINT session_harness_usage_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_harness_usage_session_id ON session_harness_usage (session_id);
CREATE UNIQUE INDEX session_harness_usage_session_kind_name_unique ON session_harness_usage (session_id, kind, name);

-- Knowledge-base (OKF) paths each session node read, searched, listed or wrote; rebuilt delete-then-insert by okf-access-writer.ts.
CREATE TABLE session_okf_access (
  id serial,
  session_id integer NOT NULL,
  -- Repo-relative file path, or a folder ending in / (repo root = /).
  path_key character varying(1024) NOT NULL,
  -- read | grep | list | write.
  op character varying(8) NOT NULL,
  -- Read or grep of a path this node had already written.
  after_own_edit boolean DEFAULT false NOT NULL,
  -- UTF-8 bytes of tool results attributed to the path; 0 for write.
  bytes bigint DEFAULT 0 NOT NULL,
  calls integer DEFAULT 0 NOT NULL,
  -- 1-based rank of the path first access within the node.
  seq integer NOT NULL,
  CONSTRAINT session_okf_access_pkey PRIMARY KEY (id),
  CONSTRAINT session_okf_access_session_path_op_edit_key UNIQUE (session_id, path_key, op, after_own_edit),
  CONSTRAINT session_okf_access_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT session_okf_access_op_check CHECK (((op)::text = ANY ((ARRAY['read'::character varying, 'grep'::character varying, 'list'::character varying, 'write'::character varying])::text[])))
);

-- Latest user-prompt count reported for a session, only ever raised; written by the post-turn-analysis config request.
CREATE TABLE session_prompt_watermark (
  session_id integer NOT NULL,
  prompt_watermark integer NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT session_prompt_watermark_pkey PRIMARY KEY (session_id),
  CONSTRAINT session_prompt_watermark_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);

-- Distinct transcript requestIds of a session; rewritten with every session_stats upsert, used to tell utility OTEL calls from transcript calls.
CREATE TABLE session_request_ids (
  session_id integer NOT NULL,
  request_id character varying(255) NOT NULL,
  CONSTRAINT session_request_ids_pk PRIMARY KEY (session_id, request_id),
  CONSTRAINT session_request_ids_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_request_ids_request_id ON session_request_ids (request_id);

-- Pre-computed per-session metrics (tokens, work time, edits, list flags, OTEL status); one row per session node, written by session-stats-writer.ts on ingest, import and recompute.
CREATE TABLE session_stats (
  session_id integer NOT NULL,
  -- Model of the session transcript (may carry a -YYYYMMDD suffix).
  model character varying,
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  -- Total cache-creation tokens = cache_write_5m_tokens + cache_write_1h_tokens.
  cache_write_tokens bigint DEFAULT 0 NOT NULL,
  -- Active time in ms: per prompt, last assistant reply minus prompt time, summed.
  work_time_ms bigint DEFAULT 0 NOT NULL,
  files_edited_written integer DEFAULT 0 NOT NULL,
  -- Lines written by Edit/Write (no delta, no removals); differs from the diff-based lines_added / lines_removed.
  lines_changed integer DEFAULT 0 NOT NULL,
  image_count integer DEFAULT 0 NOT NULL,
  image_total_bytes bigint DEFAULT 0 NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  mcp_calls_total integer DEFAULT 0 NOT NULL,
  mcp_calls_by_server jsonb DEFAULT '{}'::jsonb NOT NULL,
  cache_write_5m_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_1h_tokens bigint DEFAULT 0 NOT NULL,
  -- Diff-based added lines over the Edit/Write calls that carried a diff (see diff_lines_covered_calls).
  lines_added integer DEFAULT 0 NOT NULL,
  lines_removed integer DEFAULT 0 NOT NULL,
  commit_count integer DEFAULT 0 NOT NULL,
  pr_count integer DEFAULT 0 NOT NULL,
  turn_count integer DEFAULT 0 NOT NULL,
  -- Edit/Write calls that carried a diff; out of diff_lines_total_calls.
  diff_lines_covered_calls integer DEFAULT 0 NOT NULL,
  diff_lines_total_calls integer DEFAULT 0 NOT NULL,
  token_by_service_tier jsonb DEFAULT '{}'::jsonb NOT NULL,
  -- Count of server web-search requests; priced per request, not per token.
  web_search_requests bigint DEFAULT 0 NOT NULL,
  -- Subset of input_tokens billed in fast mode (not additional tokens).
  input_tokens_fast bigint DEFAULT 0 NOT NULL,
  -- Subset of output_tokens billed in fast mode (not additional tokens).
  output_tokens_fast bigint DEFAULT 0 NOT NULL,
  -- Denormalised OTEL cost in micro-USD (sum of logs_otel.cost_usd_micros); NULL = no telemetry signal. Written only by upsertSessionTelemetryCost().
  telemetry_cost bigint,
  -- Own-scope in-repo changed files; NULL = change surface never computed (also cs_folders_touched, cs_outside_repo_files).
  cs_changed_files integer,
  cs_folders_touched integer,
  cs_outside_repo_files integer,
  -- Set whenever the change-surface extractor ran, including zero changes; NULL = not computed or repo root unknown.
  cs_computed_at timestamp with time zone,
  -- Highest Claude Code version on this transcript; readers prefer it over claude_version_otel. NULL = unknown.
  claude_version character varying(64),
  -- Highest OTEL service.version seen for the session; only raised. NULL = unknown.
  claude_version_otel character varying(64),
  -- Latest hook OTEL status: ok | partial | none | unknown; NULL = never reported.
  otel_state character varying(16),
  -- Why OTEL is missing or partial; NULL when ok or not reported.
  otel_reason character varying(32),
  otel_status jsonb,
  -- Session-list flag: model of the first main (non-sidechain) assistant line; root transcripts only.
  main_model character varying,
  has_workflow boolean DEFAULT false NOT NULL,
  has_main_assistant boolean DEFAULT false NOT NULL,
  -- Rules version the session-list flags were computed with; NULL = pending for the startup backfill.
  list_flags_version smallint,
  -- Line count of the session own claude log; NULL = no claude log or not computed yet.
  claude_line_count integer,
  CONSTRAINT session_stats_pkey PRIMARY KEY (session_id),
  CONSTRAINT session_stats_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_stats_list_flags_pending ON session_stats (session_id) WHERE (list_flags_version IS NULL);

-- Per-session, per-tool call counts and durations; rebuilt delete-then-insert by session-tool-stats-writer.ts on transcript ingest.
CREATE TABLE session_tool_stats (
  session_id integer NOT NULL,
  tool_name character varying(128) NOT NULL,
  calls integer DEFAULT 0 NOT NULL,
  failures integer DEFAULT 0 NOT NULL,
  -- Calls with no result, or rejected, denied or interrupted.
  unresolved integer DEFAULT 0 NOT NULL,
  duration_covered_calls integer DEFAULT 0 NOT NULL,
  -- Only for computing the mean; concurrent calls overlap, so never show it as total tool time.
  duration_ms_total bigint DEFAULT 0 NOT NULL,
  duration_ms_max bigint DEFAULT 0 NOT NULL,
  -- Counts per fixed duration bucket (bounds in tool-stats.ts are append-only).
  duration_ms_histogram jsonb DEFAULT '[]'::jsonb NOT NULL,
  duration_by_source jsonb DEFAULT '{}'::jsonb NOT NULL,
  -- Calls issued together with other tool calls in one assistant message.
  parallel_batch_calls integer DEFAULT 0 NOT NULL,
  CONSTRAINT session_tool_stats_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
);
CREATE INDEX idx_session_tool_stats_session_id ON session_tool_stats (session_id);
CREATE UNIQUE INDEX session_tool_stats_session_tool_unique ON session_tool_stats (session_id, tool_name);

-- MCP and CLI tool calls per session node and tool; rebuilt per session tree by the background ToolUsageRebuildService (tool-usage-writer.ts), never written inline by ingest.
CREATE TABLE session_tool_usage (
  id serial,
  session_id integer NOT NULL,
  -- mcp | cli.
  channel character varying(8) NOT NULL,
  -- MCP server name or CLI tool name.
  tool text NOT NULL,
  call_count integer DEFAULT 0 NOT NULL,
  first_call_at timestamp with time zone,
  last_call_at timestamp with time zone,
  has_wrapper_data boolean DEFAULT false NOT NULL,
  aggregates jsonb NOT NULL,
  calls jsonb NOT NULL,
  -- Captured call text keyed by callId (each part capped); read only by call detail and search.
  outputs jsonb,
  CONSTRAINT session_tool_usage_pkey PRIMARY KEY (id),
  CONSTRAINT session_tool_usage_session_channel_tool_key UNIQUE (session_id, channel, tool),
  CONSTRAINT session_tool_usage_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT session_tool_usage_channel_check CHECK (((channel)::text = ANY ((ARRAY['mcp'::character varying, 'cli'::character varying])::text[])))
);

-- One row per Claude Code session or sub-agent session id; created by LogsService ingest, soft-deleted and purged by SessionsService.
CREATE TABLE sessions (
  id serial,
  session_id character varying(255) NOT NULL,
  -- session_id string of the immediate parent session or agent (not always the root); NULL = root session. No FK.
  parent_session_id character varying(255),
  -- Soft-delete flag: child data is purged, the row stays so re-uploads are rejected and the audit trail resolves.
  deleted boolean DEFAULT false NOT NULL,
  -- Workflow run folder name (wf_...) that spawned this sub-agent; NULL otherwise. No FK.
  workflow_run_id character varying(255),
  -- snapshot_id of the owner harness_snapshots row this session is bound to; set once, never overwritten; NULL = none yet. No FK.
  harness_snapshot_id character varying(64),
  -- snapshot_id of the owner okf_snapshots row this root session is bound to; set once; NULL for sub-agents and older hooks. No FK.
  okf_snapshot_id character varying(64),
  -- NULL = session_tool_usage rows pending rebuild by the background drain; otherwise the extractor version they were built with.
  tool_usage_version smallint,
  -- Sub-agent Task description from its .meta.json, trimmed and capped at 255 characters; NULL for main sessions and for agents uploaded without one.
  agent_description character varying(255),
  -- Workflow phase from a workflow sub-agent's .meta.json, trimmed and capped at 255 characters; NULL otherwise.
  workflow_phase character varying(255),
  CONSTRAINT sessions_pkey PRIMARY KEY (id),
  CONSTRAINT sessions_session_id_unique UNIQUE (session_id)
);
CREATE INDEX idx_sessions_tool_usage_pending ON sessions (id) WHERE ((tool_usage_version IS NULL) AND (NOT deleted));
CREATE INDEX idx_sessions_tool_usage_version ON sessions (tool_usage_version) WHERE (tool_usage_version IS NOT NULL);
CREATE INDEX sessions_deleted_idx ON sessions (session_id) WHERE (deleted = true);
CREATE INDEX sessions_harness_snapshot_id_idx ON sessions (harness_snapshot_id);
CREATE INDEX sessions_okf_snapshot_id_idx ON sessions (okf_snapshot_id);
CREATE INDEX sessions_parent_session_id_idx ON sessions (parent_session_id);
CREATE INDEX sessions_workflow_run_id_idx ON sessions (workflow_run_id);

-- Team membership and per-member roles; written by TeamsService.
CREATE TABLE team_members (
  team_id integer NOT NULL,
  user_id integer NOT NULL,
  can_invite boolean DEFAULT false NOT NULL,
  joined_at timestamp with time zone DEFAULT now() NOT NULL,
  -- Restricted mode only: full-team analytics and every member session, but never prompt text.
  is_manager boolean DEFAULT false NOT NULL,
  -- Restricted mode only: every member session with prompts, but no analytics or reports.
  is_adlc_trainer boolean DEFAULT false NOT NULL,
  -- NULL = member has not acknowledged the access-mode disclosure and is hidden from owner and trainer views.
  disclosure_acknowledged_at timestamp with time zone,
  CONSTRAINT team_members_pkey PRIMARY KEY (team_id, user_id),
  CONSTRAINT team_members_team_id_fkey FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
  CONSTRAINT team_members_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_team_members_user_id ON team_members (user_id);

-- Team analysis config of one team repository link (includes session attribution definitions); written via team-repo-config.ts. No row = team uses defaults.
CREATE TABLE team_repo_config (
  team_repository_id integer NOT NULL,
  config jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT team_repo_config_pkey PRIMARY KEY (team_repository_id),
  CONSTRAINT team_repo_config_team_repository_id_fkey FOREIGN KEY (team_repository_id) REFERENCES team_repositories(id) ON DELETE CASCADE
);

-- Pending team-scope stats recompute after a repository is added to a team; drained by TeamRepoRecomputeService, row deleted on success.
CREATE TABLE team_repo_recompute_queue (
  team_repository_id integer NOT NULL,
  -- pending | processing | failed (failed = gave up after the retry limit, see last_error).
  status character varying(16) DEFAULT 'pending'::character varying NOT NULL,
  attempts integer DEFAULT 0 NOT NULL,
  last_error text,
  enqueued_at timestamp with time zone DEFAULT now() NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT team_repo_recompute_queue_pkey PRIMARY KEY (team_repository_id),
  CONSTRAINT team_repo_recompute_queue_team_repository_id_fkey FOREIGN KEY (team_repository_id) REFERENCES team_repositories(id) ON DELETE CASCADE
);

-- Team list of monitored CLI tools for one team repository link; written by ToolMonitorConfigService (team owner only).
CREATE TABLE team_repo_tool_monitor_config (
  team_repository_id integer NOT NULL,
  config jsonb NOT NULL,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT team_repo_tool_monitor_config_pkey PRIMARY KEY (team_repository_id),
  CONSTRAINT team_repo_tool_monitor_config_team_repository_id_fkey FOREIGN KEY (team_repository_id) REFERENCES team_repositories(id) ON DELETE CASCADE
);

-- Repository URLs linked to a team (by URL, not by repositories row); written by TeamsService, AdminService and the repo URL backfill. Owns team_repo_config, team_repo_tool_monitor_config and team_repo_recompute_queue.
CREATE TABLE team_repositories (
  id serial,
  team_id integer NOT NULL,
  repo_url character varying(4000) NOT NULL,
  added_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT team_repositories_pkey PRIMARY KEY (id),
  CONSTRAINT team_repositories_team_id_repo_url_unique UNIQUE (team_id, repo_url),
  CONSTRAINT team_repositories_team_id_fkey FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE
);
CREATE INDEX idx_team_repositories_repo_url ON team_repositories (repo_url);

-- Teams; written by TeamsService. Deleting the owner is blocked (owner_id ON DELETE RESTRICT); account deletion handles owned teams first.
CREATE TABLE teams (
  id serial,
  name character varying NOT NULL,
  owner_id integer NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  -- transparent = every member sees every member session; restricted = visibility follows team_members.is_manager / is_adlc_trainer.
  access_mode team_access_mode DEFAULT 'restricted'::team_access_mode NOT NULL,
  CONSTRAINT teams_pkey PRIMARY KEY (id),
  CONSTRAINT teams_name_unique UNIQUE (name),
  CONSTRAINT teams_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE INDEX idx_teams_owner_id ON teams (owner_id);

-- Append-only log of turn-end cost advisor runs (submitted or failed only); written by TurnEndCostAdvisorService, orphans purged by a scheduler.
CREATE TABLE turn_end_advisor_runs (
  id serial,
  eval_session_id character varying(255),
  started_at timestamp with time zone NOT NULL,
  finished_at timestamp with time zone NOT NULL,
  -- submitted | failed.
  outcome character varying(20) NOT NULL,
  summary_general text,
  cost_factors jsonb,
  harness_advice jsonb,
  failure_reason text,
  model character varying(64),
  cost_usd numeric(12,6),
  input_tokens bigint DEFAULT 0 NOT NULL,
  output_tokens bigint DEFAULT 0 NOT NULL,
  cache_read_tokens bigint DEFAULT 0 NOT NULL,
  cache_write_tokens bigint DEFAULT 0 NOT NULL,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  -- session_id string of the invoking session, no FK: the session may not be ingested yet.
  session_id character varying(255) NOT NULL,
  -- User whose API key recorded the run; reads require it to equal the session owner, NULL never matches.
  user_id integer,
  CONSTRAINT turn_end_advisor_runs_pkey PRIMARY KEY (id),
  CONSTRAINT turn_end_advisor_runs_user_id_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_turn_end_advisor_runs_user_id ON turn_end_advisor_runs (user_id);
CREATE INDEX turn_end_advisor_runs_session_user_idx ON turn_end_advisor_runs (session_id, user_id, started_at DESC);

-- Staged async uploads (/api/v2/logs) waiting for the worker; written by UploadQueueService, processed by UploadQueueSchedulerService, row deleted on success.
CREATE TABLE upload_queue (
  id serial,
  file_name character varying(255) NOT NULL,
  size_bytes bigint NOT NULL,
  received_at timestamp with time zone DEFAULT now() NOT NULL,
  -- session_id string sent by the hook; no FK (the session may not exist yet).
  session_id character varying(255) NOT NULL,
  log_type character varying(50) NOT NULL,
  user_id integer NOT NULL,
  parent_session_id character varying(255),
  workflow_run_id character varying(255),
  status upload_queue_status DEFAULT 'pending'::upload_queue_status NOT NULL,
  error_message text,
  updated_at timestamp with time zone DEFAULT now() NOT NULL,
  -- Hook-generated id of a chunked upload; NULL for single-request uploads.
  upload_id character varying(255),
  chunks_received integer,
  total_chunks integer,
  -- true once a rejected_foreign_session warning was returned to the hook.
  warning_delivered boolean DEFAULT false NOT NULL,
  -- Set only when the upload carries a full harness snapshot body, so the id counts as known while the row is in flight. No FK.
  harness_snapshot_id character varying(64),
  -- Set only when the upload carries a full OKF snapshot body, so the id counts as known while the row is in flight. No FK.
  okf_snapshot_id character varying(64),
  -- Processing attempts; transient database errors retry until the limit.
  attempts integer DEFAULT 0 NOT NULL,
  -- With status failed: server (Log Hub could not process a good file) | file (broken body); NULL on older rows.
  error_kind character varying(16),
  -- Sub-agent Task description sent with the upload, copied to sessions.agent_description when the row is processed; NULL otherwise.
  agent_description character varying(255),
  -- Workflow phase sent with the upload, copied to sessions.workflow_phase when the row is processed; NULL otherwise.
  workflow_phase character varying(255),
  CONSTRAINT upload_queue_pkey PRIMARY KEY (id),
  CONSTRAINT upload_queue_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_upload_queue_session_id_received_at ON upload_queue (session_id, received_at);
CREATE INDEX idx_upload_queue_status_received_at ON upload_queue (status, received_at);
CREATE UNIQUE INDEX idx_upload_queue_upload_id ON upload_queue (upload_id) WHERE (upload_id IS NOT NULL);
CREATE INDEX idx_upload_queue_user_id ON upload_queue (user_id);
CREATE INDEX idx_upload_queue_user_id_status ON upload_queue (user_id, status);

-- Append-only worker measurements, one per processing attempt, for the admin upload queue stats; written and pruned by UploadQueueSchedulerService.
CREATE TABLE upload_queue_measurements (
  id serial,
  -- session_id string; no FK (the session may never have been ingested or is already purged).
  session_id character varying(255) NOT NULL,
  log_type character varying(50) NOT NULL,
  started_at timestamp with time zone NOT NULL,
  finished_at timestamp with time zone NOT NULL,
  duration_ms integer NOT NULL,
  -- finished_at minus the queue row received_at.
  queue_latency_ms bigint NOT NULL,
  size_bytes bigint NOT NULL,
  -- success | failure.
  outcome character varying(20) NOT NULL,
  CONSTRAINT upload_queue_measurements_pkey PRIMARY KEY (id)
);
CREATE INDEX idx_upload_queue_measurements_finished_at ON upload_queue_measurements (finished_at);

-- Sessions a user starred; written by RepositoriesService.
CREATE TABLE user_favorite_sessions (
  user_id integer NOT NULL,
  session_id integer NOT NULL,
  CONSTRAINT user_favorite_sessions_pkey PRIMARY KEY (user_id, session_id),
  CONSTRAINT user_favorite_sessions_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE,
  CONSTRAINT user_favorite_sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_user_favorite_sessions_session_id ON user_favorite_sessions (session_id);

-- Generic per-user key/value settings owned by the client; the server never interprets names or values. Written by UserSettingsService.
CREATE TABLE user_settings (
  user_id integer NOT NULL,
  setting_name character varying(100) NOT NULL,
  -- Opaque to the server (often JSON); capped at 64 KB by the DTO.
  setting_value text,
  CONSTRAINT user_settings_pkey PRIMARY KEY (user_id, setting_name),
  CONSTRAINT user_settings_user_id_fkey FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Log Hub accounts; written by UsersService (sign-up, identify, admin) and by import, which creates placeholder owners by email.
CREATE TABLE users (
  id serial,
  email character varying NOT NULL,
  -- NULL for accounts without a password (identify-only or not yet confirmed); imported placeholder users hold a sentinel hash that can never log in.
  password_hash character varying,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  role user_role DEFAULT 'user'::user_role NOT NULL,
  -- NULL = email not confirmed yet (only meaningful in auth modes that require confirmation).
  email_confirmed_at timestamp with time zone,
  CONSTRAINT users_pkey PRIMARY KEY (id),
  CONSTRAINT users_email_unique UNIQUE (email)
);
CREATE INDEX idx_users_role ON users (role);
